#!/usr/bin/env python3
"""Generates Core/Src/fixed_sin_table.c: a quarter-wave sine table in Q16.16.

Entry i is sin(i/1024 * 90 degrees) * 65536, for i = 0..1024 inclusive.
fx_sin() in fixed.c mirrors it to cover the full circle.

Run from the repo root:  python3 tools/gen_sin_table.py
"""
import math
import os

QUARTER = 1024  # table steps per 90 degrees (FX_ANGLE_FULL / 4 in fixed.h)
ONE = 1 << 16   # 1.0 in Q16.16

values = [round(math.sin(i * math.pi / 2 / QUARTER) * ONE) for i in range(QUARTER + 1)]

lines = [
    "// Generated by tools/gen_sin_table.py -- do not edit by hand",
    '#include "fixed.h"',
    "",
    f"const fx fx_sin_table[{QUARTER + 1}] = {{",
]
for i in range(0, len(values), 8):
    lines.append("\t" + ", ".join(str(v) for v in values[i:i + 8]) + ",")
lines.append("};")

out = os.path.join(os.path.dirname(__file__), "..", "Core", "Src", "fixed_sin_table.c")
with open(out, "w") as f:
    f.write("\n".join(lines) + "\n")
print(f"wrote {len(values)} entries to {os.path.normpath(out)}")
